('b2222222-0000-0000-0000-000000000001', 'Push–Pull–Legs (PPL)', 'Periodized 6-day split ensuring 48h muscle recovery between Push, Pull, and Leg sessions.', 'PPL', 'INTERMEDIATE', '6 Days/Wk', 500, 23),
('b2222222-0000-0000-0000-000000000002', 'Upper–Lower Split', 'High-frequency split targeting upper body and lower body on alternating days for max power & hypertrophy.', 'UPPER_LOWER', 'INTERMEDIATE', '4-5 Days/Wk', 450, 22),
('b2222222-0000-0000-0000-000000000003', 'Bro Split', 'Classic 5-day bodybuilding routine training one main muscle group per workout session.', 'BRO_SPLIT', 'INTERMEDIATE', '5 Days/Wk', 420, 24),
('b2222222-0000-0000-0000-000000000004', 'Push–Pull–Legs + Upper–Lower', 'Hybrid 5-day routine blending 3 heavy PPL strength days with 2 high-volume Upper/Lower hypertrophy days.', 'PPL_UPPER_LOWER_HYBRID', 'PRO', '5 Days/Wk', 550, 23),
('b2222222-0000-0000-0000-000000000005', 'Arnold Split', 'Golden era 6-day split supersetting opposing antagonist muscle groups for extreme pump and expansion.', 'ARNOLD_SPLIT', 'PRO', '6 Days/Wk', 600, 23),
('b2222222-0000-0000-0000-000000000006', 'Push–Pull + Legs', 'Streamlined 3-day split combining upper body push & pull movements followed by a dedicated lower body day.', 'PUSH_PULL_LEGS_3DAY', 'BEGINNER', '3 Days/Wk', 400, 22),
('b2222222-0000-0000-0000-000000000007', 'Full Body Split', 'High frequency 3-day resistance training activating all major muscle groups every session.', 'FULL_BODY_SPLIT', 'ALL', '3 Days/Wk', 480, 22),
('b2222222-0000-0000-0000-000000000008', 'Upper–Lower–Arms Split', '4-day split adding a dedicated direct arm specialization day to balanced upper/lower progression.', 'UPPER_LOWER_ARMS', 'INTERMEDIATE', '4 Days/Wk', 420, 23),
('b2222222-0000-0000-0000-000000000009', 'Chest–Back–Legs–Shoulders–Arms', 'Dedicated 5-day muscle specialization split giving every primary muscle group full recovery and maximum load.', 'CHEST_BACK_LEGS_SHOULDERS_ARMS', 'INTERMEDIATE', '5 Days/Wk', 440, 25),
('b2222222-0000-0000-0000-000000000010', 'Torso–Limbs Split', 'Alternating split pairing chest, back, & shoulders (Torso) on Day 1, and biceps, triceps, & legs (Limbs) on Day 2.', 'TORSO_LIMBS', 'INTERMEDIATE', '4 Days/Wk', 460, 22),
('b2222222-0000-0000-0000-000000000011', 'Zumba / Dance Cardio', 'Rhythmic aerobic dance workout burning calories through dynamic choreography and high-energy music.', 'ZUMBA_DANCE', 'BEGINNER', '45 Mins', 350, 20),
('b2222222-0000-0000-0000-000000000012', 'HIIT Cardio', 'Short explosive work bursts alternated with brief rest recovery intervals for maximum post-exercise fat oxidation.', 'HIIT_CARDIO', 'PRO', '25 Mins', 400, 22),
('b2222222-0000-0000-0000-000000000013', 'LISS Cardio', 'Sustained low-heart-rate cardio promoting fat utilization, active recovery, and cardiovascular stamina.', 'LISS_CARDIO', 'BEGINNER', '45 Mins', 250, 20),
('b2222222-0000-0000-0000-000000000014', 'Steady-State Cardio', 'Moderate intensity aerobic exercise maintaining constant pace for aerobic capacity and endurance.', 'STEADY_STATE_CARDIO', 'ALL', '35 Mins', 300, 21),
('b2222222-0000-0000-0000-000000000015', 'Cycling Cardio', 'Low-impact stationary or outdoor cycling training leg endurance, power output, and cardiovascular health.', 'CYCLING_CARDIO', 'ALL', '45 Mins', 450, 20),
('b2222222-0000-0000-0000-000000000016', 'Running / Jogging', 'Outdoor or treadmill running protocol building VO2 max, bone density, and leg stamina.', 'RUNNING_JOGGING', 'INTERMEDIATE', '30 Mins', 380, 20),
('b2222222-0000-0000-0000-000000000017', 'Swimming', 'Full-body zero-impact aquatic aerobic workout engaging lats, shoulders, core, and respiratory endurance.', 'SWIMMING', 'INTERMEDIATE', '45 Mins', 500, 20),
('b2222222-0000-0000-0000-000000000018', 'Rowing', 'Full-body ergometer conditioning loading posterior chain, lats, legs, and lungs in powerful strokes.', 'ROWING', 'INTERMEDIATE', '30 Mins', 420, 20),
('b2222222-0000-0000-0000-000000000019', 'Stair Climber', 'Continuous stair climbing targeting glute and quad hypertrophy while elevating aerobic heart rate.', 'STAIR_CLIMBER', 'INTERMEDIATE', '30 Mins', 360, 20),
